// Synthetic replica of react-native-vector-icons published output: untranspiled
// JSX inside a published .js file. Metro applies the React Native Babel preset
// to node_modules like this; a bundler that does not transform JSX in
// node_modules .js files cannot parse this entry without a per-package opt-in.
export const VECTOR_ICONS_OK = "VECTOR_ICONS_OK";

export default function createIconSet(glyphMap, fontFamily) {
  function Icon(props) {
    const glyph = glyphMap[props.name] ?? 0x003f;
    // Raw JSX shipped in a .js file — requires JSX transformation at bundle time.
    return <RNSVGText style={{ fontFamily }}>{String.fromCodePoint(glyph)}</RNSVGText>;
  }
  Icon.glyphMap = glyphMap;
  return Icon;
}
